package com.healthcare.portal.controller;
import com.healthcare.portal.dto.PaymentRequests.*; import com.healthcare.portal.security.CustomUserDetails; import com.healthcare.portal.service.*; import org.springframework.http.ResponseEntity; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/payments") public class PaymentController { private final PaymentService service; private final AuthService auth; public PaymentController(PaymentService s,AuthService a){service=s;auth=a;} @PostMapping("/refund/{appointmentId}") public ResponseEntity<?> refund(@AuthenticationPrincipal CustomUserDetails u,@PathVariable Long appointmentId){return ResponseEntity.ok(service.refund(auth.getUserByEmail(u.getUsername()).getId(),appointmentId));} @PostMapping("/create-order") public ResponseEntity<?> create(@AuthenticationPrincipal CustomUserDetails u,@RequestBody CreateOrder r){return ResponseEntity.ok(service.createOrder(auth.getUserByEmail(u.getUsername()).getId(),r.getAppointmentId()));} @PostMapping("/verify") public ResponseEntity<?> verify(@AuthenticationPrincipal CustomUserDetails u,@RequestBody VerifyPayment r){return ResponseEntity.ok(service.verify(auth.getUserByEmail(u.getUsername()).getId(),r.getOrderId(),r.getPaymentId(),r.getSignature()));} }
